void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    // Detect potential overflow before performing the addition
    if (activity[var] > 1e100 - inc) {
        const double scale = 1e-100;
        // Scale down all variable activities to keep numbers in a safe range
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        // Scale down the increment factor as well
        var_inc *= scale;
    }
    activity[var] += inc;
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
